<script setup lang="ts">
import RecordPagination from '../components/RecordPagination.vue'
const pageSize = ref(20)
import { onBeforeUnmount,onMounted,reactive,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ElMessage,ElMessageBox } from 'element-plus'
import * as api from '../api/system'
import type { Account,Department,Task,AuditLog,UserInput,Diagnostics } from '../api/system'
import { actionNames,stateNames } from '../api/training'
import { stateLabel } from '../api/manuscripts'
import { session,loadSession } from '../session'
const route=useRoute(),router=useRouter(),tabs=['users','departments','tasks','logs'],tab=ref(tabs.includes(String(route.query.tab))?String(route.query.tab):'users')
const users=ref<Account[]>([]),departments=ref<Department[]>([]),options=ref<Department[]>([]),tasks=ref<Task[]>([]),logs=ref<AuditLog[]>([]),diagnostics=ref<Diagnostics>()
const q=ref(''),role=ref(''),enabled=ref(''),status=ref(''),page=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),dialogError=ref(''),userOpen=ref(false),departmentOpen=ref(false),userId=ref<string>(),departmentId=ref<string>()
const user=reactive<UserInput>({username:'',displayName:'',password:'',role:'MEMBER',enabled:true,organizationIds:[]}),department=reactive({name:'',enabled:true})
let ticket=0,alive=true,timer:ReturnType<typeof setInterval>|undefined
const operations:Record<string,string>={USER_CREATED:'创建账号',USER_UPDATED:'修改账号',DEPARTMENT_CREATED:'创建部门',DEPARTMENT_UPDATED:'修改部门'}
const actions:Record<string,string>={...actionNames,AUDIT:'质量评估',CLEAN:'数据清洗',CONTENT:'内容复用检查',GRAMMAR_RULES:'快速语法检查',GRAMMAR_MODEL:'模型语法检查',IMAGE_TEXT:'图文检查',FORMAL:'送审检测'}
const states:Record<string,string>={...stateLabel,...stateNames,WAITING_SERVICE:'等待检测服务',WAITING_RESOURCE:'等待模型资源',PARTIAL_FAILED:'部分失败'}
function beforeDialogClose(done:()=>void){if(!saving.value)done()}
async function load(){const token=++ticket;loading.value=true;try{if(tab.value==='users'){const result=await api.users(page.value,q.value,role.value,enabled.value,pageSize.value);if(alive&&token===ticket){users.value=result.items;total.value=result.total}}else if(tab.value==='departments'){const result=await api.organizations(page.value,q.value,pageSize.value);if(alive&&token===ticket){departments.value=result.items;total.value=result.total}}else if(tab.value==='tasks'){const result=await api.tasks(page.value,q.value,status.value,pageSize.value);if(alive&&token===ticket){tasks.value=result.items;total.value=result.total}}else{const result=await api.logs(page.value,q.value,pageSize.value);if(alive&&token===ticket){logs.value=result.items;total.value=result.total}}if(alive&&token===ticket)error.value=''}catch(value){if(alive&&token===ticket)error.value=value instanceof Error?value.message:'读取管理数据失败'}finally{if(alive&&token===ticket)loading.value=false}}
async function diagnose(){try{const value=await api.diagnostics();if(alive)diagnostics.value=value}catch(value){if(alive)error.value=value instanceof Error?value.message:'读取服务状态失败'}}
function search(){page.value=1;void load()}
async function changeTab(){q.value='';page.value=1;role.value='';enabled.value='';status.value='';await router.replace({query:{...route.query,tab:tab.value}});await load();if(tab.value==='tasks')void diagnose()}
watch(()=>route.query.tab,value=>{if(tabs.includes(String(value))&&value!==tab.value){tab.value=String(value);void changeTab()}})
async function editUser(row?:Account){dialogError.value='';try{options.value=await api.organizationOptions();userId.value=row?.id;Object.assign(user,{username:row?.username??'',displayName:row?.displayName??'',password:'',role:row?.role??'MEMBER',enabled:row?.enabled??true,organizationIds:row?.organizations.map(o=>o.id)??[]});userOpen.value=true}catch(value){error.value=value instanceof Error?value.message:'读取部门失败'}}
async function saveUser(){dialogError.value='';if(!user.displayName.trim()){dialogError.value='请填写姓名';return}if(user.role==='MEMBER'&&user.enabled&&!user.organizationIds.length){dialogError.value='请为创作者选择部门';return}if(!userId.value&&(!user.username||!user.password||Array.from(user.password).length<8)){dialogError.value='请填写账号和至少8位的初始密码';return}saving.value=true;try{await api.saveUser(userId.value,{...user,organizationIds:[...user.organizationIds]});userOpen.value=false;user.password='';ElMessage.success('账号已保存');if(userId.value===session.user?.userId)await loadSession();await load()}catch(value){dialogError.value=value instanceof Error?value.message:'保存失败'}finally{saving.value=false}}
async function toggleUser(row:Account){try{await ElMessageBox.confirm(`确认${row.enabled?'停用':'启用'}账号“${row.displayName}”？`,'账号状态',{confirmButtonText:'确认',cancelButtonText:'取消'})}catch{return}try{await api.saveUser(row.id,{displayName:row.displayName,role:row.role,enabled:!row.enabled,organizationIds:row.organizations.filter(o=>o.enabled).map(o=>o.id)});ElMessage.success('账号状态已更新');await load()}catch(value){error.value=value instanceof Error?value.message:'更新失败'}}
function editDepartment(row?:Department){dialogError.value='';departmentId.value=row?.id;Object.assign(department,{name:row?.name??'',enabled:row?.enabled??true});departmentOpen.value=true}
async function saveDepartment(){dialogError.value='';if(!department.name.trim()){dialogError.value='请填写部门名称';return}saving.value=true;try{await api.saveOrganization(departmentId.value,{...department});departmentOpen.value=false;ElMessage.success('部门已保存');await load();await loadSession()}catch(value){dialogError.value=value instanceof Error?value.message:'保存失败'}finally{saving.value=false}}
async function toggleDepartment(row:Department){try{await ElMessageBox.confirm(`确认${row.enabled?'停用':'启用'}部门“${row.name}”？`,'部门状态',{confirmButtonText:'确认',cancelButtonText:'取消'})}catch{return}try{await api.saveOrganization(row.id,{name:row.name,enabled:!row.enabled});ElMessage.success('部门状态已更新');await load()}catch(value){error.value=value instanceof Error?value.message:'更新失败'}}
const time=(value:string|null)=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—'
function logText(item:AuditLog){try{const value=JSON.parse(item.details);return [value.username,value.name,value.role&&api.roles[value.role],typeof value.enabled==='boolean'?(value.enabled?'启用':'停用'):''].filter(Boolean).join(' · ')}catch{return '已记录'}}
onMounted(()=>{void load();timer=setInterval(()=>{if(tab.value==='tasks'&&!loading.value)void load()},10000);if(tab.value==='tasks')void diagnose()});onBeforeUnmount(()=>{alive=false;ticket++;if(timer)clearInterval(timer)})
</script>
<template><div class="system-page"><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><div class="section-heading"><div><h2>{{ ({users:'账号管理',departments:'部门管理',tasks:'运行与任务',logs:'管理操作记录'} as Record<string,string>)[tab] }}</h2><span class="muted">管理南京传媒学院部门、账号权限及运行记录。</span></div><el-tag>管理员</el-tag></div><el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane label="账号管理" name="users"/><el-tab-pane label="部门管理" name="departments"/><el-tab-pane label="运行与任务" name="tasks"/><el-tab-pane label="操作记录" name="logs"/></el-tabs>
<div class="system-filters"><el-input v-model="q" :placeholder="tab==='users'?'搜索账号或姓名':tab==='departments'?'搜索部门':tab==='logs'?'搜索操作人或操作类型':'搜索任务对象'" aria-label="管理列表搜索" clearable @keyup.enter="search"/><template v-if="tab==='users'"><el-select v-model="role" clearable placeholder="全部角色" aria-label="账号角色" @change="search"><el-option v-for="(name,key) in api.roles" :key="key" :value="key" :label="name"/></el-select><el-select v-model="enabled" clearable placeholder="全部状态" aria-label="账号启停状态" @change="search"><el-option value="true" label="启用"/><el-option value="false" label="停用"/></el-select></template><el-select v-if="tab==='tasks'" v-model="status" clearable placeholder="全部状态" aria-label="任务状态" @change="search"><el-option v-for="(name,key) in {ACTIVE:'运行与等待',COMPLETED:'完成',FAILED:'失败',CANCELLED:'取消',INTERRUPTED:'中断'}" :key="key" :value="key" :label="name"/></el-select><el-button @click="search">查询</el-button><el-button @click="load">刷新</el-button><el-button v-if="tab==='users'" type="primary" @click="editUser()">新增账号</el-button><el-button v-if="tab==='departments'" type="primary" @click="editDepartment()">新增部门</el-button><el-button v-if="tab==='tasks'" @click="diagnose">检查服务状态</el-button></div>
<div v-if="tab==='tasks'&&diagnostics" class="service-grid"><div><span>业务服务</span><strong>{{diagnostics.java==='READY'?'运行中':'不可用'}}</strong></div><div><span>数据库</span><strong>{{diagnostics.database==='READY'?'已连接':'不可用'}}</strong></div><div><span>内容检测</span><strong>{{!diagnostics.detector.ready?'未启动 / 不可用':diagnostics.detector.busy?'计算中':'就绪'}}</strong></div><div><span>图片文字识别</span><strong>{{!diagnostics.ocr.ready?'未启动 / 不可用':diagnostics.ocr.busy?'计算中':'就绪'}}</strong></div></div>
<div v-loading="loading"><el-table v-if="tab==='users'" :data="users" empty-text="未找到账号"><el-table-column prop="username" label="账号" min-width="140"/><el-table-column prop="displayName" label="姓名" min-width="140"/><el-table-column label="角色" width="110"><template #default="{row}"><el-tag>{{api.roles[row.role]}}</el-tag></template></el-table-column><el-table-column label="所属部门" min-width="200"><template #default="{row}">{{row.organizations.map((o:Department)=>o.name+(o.enabled?'':'（停用）')).join(' / ') || (row.role==='MEMBER'?'未分配':'全校工作范围')}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button link @click="editUser(row)">编辑</el-button><el-button link :disabled="row.id===session.user?.userId" :type="row.enabled?'danger':'primary'" @click="toggleUser(row)">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table>
<el-table v-else-if="tab==='departments'" :data="departments" empty-text="未找到部门"><el-table-column prop="name" label="部门名称" min-width="230"/><el-table-column prop="memberCount" label="启用成员" width="110"/><el-table-column prop="manuscriptCount" label="稿件数量" width="110"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button link @click="editDepartment(row)">编辑</el-button><el-button link :type="row.enabled?'danger':'primary'" @click="toggleDepartment(row)">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table>
<el-table v-else-if="tab==='tasks'" :data="tasks" empty-text="暂无匹配任务"><el-table-column prop="target" label="任务对象" min-width="220"/><el-table-column label="类型" min-width="150"><template #default="{row}">{{actions[row.action] || row.action}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.status==='FAILED'?'danger':row.status==='RUNNING'?'warning':'info'">{{states[row.status] || row.status}}</el-tag></template></el-table-column><el-table-column label="创建时间" min-width="170"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column><el-table-column label="结束时间" min-width="170"><template #default="{row}">{{time(row.finishedAt)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><RouterLink v-if="row.kind==='DATA'" :to="['AUDIT','CLEAN'].includes(row.action)?'/datasets':`/training?run=${row.id}`">查看</RouterLink><span v-else class="muted">{{row.kind==='REVIEW'?'送审检测':'稿件检查'}}</span></template></el-table-column></el-table>
<el-table v-else :data="logs" empty-text="暂无管理操作记录"><el-table-column prop="actor" label="操作人" min-width="130"/><el-table-column label="操作" min-width="140"><template #default="{row}">{{operations[row.operation] || row.operation}}</template></el-table-column><el-table-column label="对象" width="130"><template #default="{row}">{{row.objectType==='SYSTEM_USER'?'账号':'部门'}} #{{row.objectId}}</template></el-table-column><el-table-column label="变更" min-width="230"><template #default="{row}">{{logText(row)}}</template></el-table-column><el-table-column label="时间" min-width="170"><template #default="{row}">{{time(row.createdAt)}}</template></el-table-column></el-table></div><RecordPagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" @change="load" /></section>
<el-dialog v-model="userOpen" :title="userId?'编辑账号':'新增账号'" width="min(580px,95vw)" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" :before-close="beforeDialogClose"><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="saveUser"><el-form-item label="登录账号" required><el-input v-model="user.username" :disabled="!!userId||saving" maxlength="64" autocomplete="off" placeholder="3—64位字母、数字或._-"/></el-form-item><el-form-item label="姓名" required><el-input v-model="user.displayName" maxlength="64" :disabled="saving"/></el-form-item><el-form-item v-if="!userId" label="初始密码" required><el-input v-model="user.password" type="password" show-password autocomplete="new-password" maxlength="64" placeholder="至少8位" :disabled="saving"/></el-form-item><el-form-item label="角色" required><el-select v-model="user.role" :disabled="saving||userId===session.user?.userId"><el-option v-for="(name,key) in api.roles" :key="key" :label="name" :value="key"/></el-select></el-form-item><el-form-item :label="user.role==='MEMBER'?'所属部门':'关联部门（可选）'" :required="user.role==='MEMBER'"><el-select v-model="user.organizationIds" multiple filterable :disabled="saving" placeholder="选择校内部门"><el-option v-for="o in options" :key="o.id" :value="o.id" :label="o.name+(o.enabled?'':'（停用）')" :disabled="!o.enabled"/></el-select></el-form-item><el-form-item label="账号状态"><el-switch v-model="user.enabled" active-text="启用" inactive-text="停用" :disabled="saving||userId===session.user?.userId"/></el-form-item><p class="muted">{{user.role==='MEMBER'?'创作者可编写、检查并送审所属部门稿件。':user.role==='REVIEWER'?'审核员可审核全校稿件，上传、清洗新闻并提交对比库入库。':'管理员可管理校内账号、部门、数据和模型。'}}</p></el-form><template #footer><el-button :disabled="saving" @click="userOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveUser">保存</el-button></template></el-dialog>
<el-dialog v-model="departmentOpen" :title="departmentId?'编辑部门':'新增部门'" width="min(500px,95vw)" :close-on-click-modal="false" :close-on-press-escape="!saving" :show-close="!saving" :before-close="beforeDialogClose"><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="saveDepartment"><el-form-item label="部门名称" required><el-input v-model="department.name" maxlength="100" :disabled="saving"/></el-form-item><el-form-item label="部门状态"><el-switch v-model="department.enabled" active-text="启用" inactive-text="停用" :disabled="saving"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="departmentOpen=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveDepartment">保存</el-button></template></el-dialog></div></template>
<style scoped>.system-filters{display:flex;gap:10px;flex-wrap:wrap;margin:14px 0}.system-filters>.el-input{width:270px}.system-filters>.el-select{width:150px}.service-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:18px 0}.service-grid>div{padding:16px;background:color-mix(in srgb,var(--el-color-primary) 6%,var(--canvas));border:1px solid var(--line)}.service-grid span{display:block;color:var(--muted);font-size:12px}.service-grid strong{display:block;font-size:18px;margin-top:10px}.system-page :deep(.el-dialog .el-select){width:100%}.system-page :deep(.el-switch__core){border-radius:0}.system-page :deep(.el-switch__action){border-radius:0}@media(max-width:900px){.service-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.system-filters>.el-input{width:100%}}</style>
